            let prior_rels_vec = db.prior_rels_for_plain_backup_import()?;
            db.import_from_backup(&target_file, &prior_rels_vec)
                .map_err(DbError::from)
                .map_err(ploke_error::Error::from)?;
            db.ensure_compilation_unit_relations()
                .map_err(ploke_error::Error::from)?;
