// ploke_bm25_indexer.rs
// BM25 integration for Ploke using the `bm25` crate v2.3.1
// - In-memory indexer that accepts batches of (Uuid, snippet)
// - Uses a code-aware tokenizer (implements bm25::Tokenizer)
// - Uses bm25::Embedder and bm25::Scorer to build sparse embeddings and score queries
// - Adds Cozo client trait + an index_batch_with_cozo method that upserts doc metadata into Cozo
// - Adds `new_from_corpus` constructor that consumes a Vec<(Uuid, String)> to compute avgdl

use std::{
    collections::{HashMap, HashSet},
    sync::Arc,
};

use bm25::{EmbedderBuilder, Scorer, Tokenizer};
use cozo::{DataValue, UuidWrapper};
use ploke_core::{CrateId, EmbeddingData, RetrievalScope, TrackingHash};
use uuid::Uuid;

use crate::{Database, DbError, NodeType};

pub mod bm25_service;

pub const TOKENIZER_VERSION: &str = "code_version_v1";

// ------------------------- Code-aware tokenizer -------------------------
// Implements bm25::Tokenizer by producing a Vec<String> of tokens from code.
#[derive(Default, Clone)]
/// Tokenizer for source code that:
/// - splits identifiers into subtokens (snake_case, camelCase, PascalCase, digits, acronyms)
/// - includes words from comments (line and block)
/// - treats non-alphanumeric symbols as separate tokens
///
/// Example:
/// ```
/// use ploke_db::bm25_index::CodeTokenizer;
/// use bm25::Tokenizer;
/// let src = "/// docs\nfn parseJSON_v2(x: i32) { x += 10; }";
/// let t = CodeTokenizer::default();
/// let toks = t.tokenize(src);
/// assert!(toks.iter().any(|t| t == "docs"));
/// assert!(toks.iter().any(|t| t == "parse"));
/// assert!(toks.iter().any(|t| t == "json"));
/// assert!(toks.iter().any(|t| t == "v2"));
/// ```
pub struct CodeTokenizer;

impl CodeTokenizer {
    /// Split an identifier into subtokens (snake_case, camelCase, PascalCase, digits, acronyms)
    fn split_identifier(ident: &str) -> Vec<String> {
        let mut parts: Vec<String> = Vec::new();
        for chunk in ident.split('_') {
            if chunk.is_empty() {
                continue;
            }
            let mut cur = String::new();
            let chars: Vec<char> = chunk.chars().collect();
            for (i, &ch) in chars.iter().enumerate() {
                if i > 0 {
                    let prev = chars[i - 1];
                    let next = chars.get(i + 1).copied();
                    let lower_to_upper = prev.is_lowercase() && ch.is_uppercase();
                    let upper_seq_then_lower = prev.is_uppercase()
                        && ch.is_uppercase()
                        && next.map_or_else(|| false, |n| n.is_lowercase());
                    // Do not split at letter<->digit boundaries; keep tokens like "v2" intact.
                    if (lower_to_upper || upper_seq_then_lower) && !cur.is_empty() {
                        parts.push(cur.to_lowercase());
                        cur.clear();
                    }
                }
                cur.push(ch);
            }
            if !cur.is_empty() {
                parts.push(cur.to_lowercase());
            }
        }
        parts
    }

    /// Extract tokens from a code string. Includes identifier subtokens, comment words, and symbols
    fn tokens_from_code(s: &str) -> Vec<String> {
        let mut out = Vec::new();
        let bytes = s.as_bytes();
        let mut i = 0usize;
        let mut code_start = 0usize;
        let len = bytes.len();

        while i < len {
            if bytes[i] == b'/' {
                if i + 1 < len && bytes[i + 1] == b'/' {
                    // Emit code before line comment
                    if code_start < i {
                        let code_part = &s[code_start..i];
                        Self::tokenize_code_part(code_part, &mut out);
                    }
                    // Extract and tokenize the comment (skip the leading slashes, handle "///")
                    let mut j = i + 2;
                    while j < len && bytes[j] != b'\n' {
                        j += 1;
                    }
                    let mut comment_slice = &s[i + 2..j];
                    while comment_slice.starts_with('/') {
                        comment_slice = &comment_slice[1..];
                    }
                    for tok in comment_slice.split(|ch: char| !ch.is_alphanumeric()) {
                        if !tok.is_empty() {
                            out.push(tok.to_lowercase());
                        }
                    }
                    // Advance past newline if present
                    if j < len && bytes[j] == b'\n' {
                        i = j + 1;
                        code_start = i;
                        continue;
                    } else {
                        i = j;
                        code_start = i;
                        break;
                    }
                } else if i + 1 < len && bytes[i + 1] == b'*' {
                    // Emit code before block comment
                    if code_start < i {
                        let code_part = &s[code_start..i];
                        Self::tokenize_code_part(code_part, &mut out);
                    }
                    // Find end of block comment
                    let mut j = i + 2;
                    let mut found_end = false;
                    while j + 1 < len {
                        if bytes[j] == b'*' && bytes[j + 1] == b'/' {
                            found_end = true;
                            break;
                        }
                        j += 1;
                    }
                    let comment_end = if found_end { j } else { len };
                    let comment_slice = &s[i + 2..comment_end];
                    for tok in comment_slice.split(|ch: char| !ch.is_alphanumeric()) {
                        if !tok.is_empty() {
                            out.push(tok.to_lowercase());
                        }
                    }
                    if found_end {
                        i = j + 2;
                        code_start = i;
                        continue;
                    } else {
                        // Reached EOF inside block comment
                        i = len;
                        code_start = i;
                        break;
                    }
                }
            }
            i += 1;
        }

        // Emit any trailing code after the last comment
        if code_start < len {
            let code_part = &s[code_start..len];
            Self::tokenize_code_part(code_part, &mut out);
        }

        out
    }

    /// Count tokens in the entire code string without allocating per-token Strings.
    /// This is guaranteed to match the length of `tokenize()` for the same input.
    /// ```
    /// use ploke_db::bm25_index::CodeTokenizer;
    /// use bm25::Tokenizer;
    /// let s = "/// docs\nfn parseJSON_v2(x: i32) { x += 10; }";
    /// let t = CodeTokenizer::default();
    /// let toks = t.tokenize(s);
    /// let count = CodeTokenizer::count_tokens_in_code(s);
    /// assert_eq!(toks.len(), count);
    /// ```
    pub fn count_tokens_in_code(s: &str) -> usize {
        let bytes = s.as_bytes();
        let mut i = 0usize;
        let mut code_start = 0usize;
        let len = bytes.len();
        let mut count = 0usize;

        while i < len {
            if bytes[i] == b'/' {
                if i + 1 < len && bytes[i + 1] == b'/' {
                    // Count tokens in code before line comment
                    if code_start < i {
                        count += Self::token_count_in_code_part(&s[code_start..i]);
                    }
                    // Count comment tokens
                    let mut j = i + 2;
                    while j < len && bytes[j] != b'\n' {
                        j += 1;
                    }
                    let mut comment_slice = &s[i + 2..j];
                    while comment_slice.starts_with('/') {
                        comment_slice = &comment_slice[1..];
                    }
                    count += comment_slice
                        .split(|ch: char| !ch.is_alphanumeric())
                        .filter(|t| !t.is_empty())
                        .count();

                    // Advance
                    if j < len && bytes[j] == b'\n' {
                        i = j + 1;
                        code_start = i;
                        continue;
                    } else {
                        i = j;
                        code_start = i;
                        break;
                    }
                } else if i + 1 < len && bytes[i + 1] == b'*' {
                    // Count tokens in code before block comment
                    if code_start < i {
                        count += Self::token_count_in_code_part(&s[code_start..i]);
                    }
                    // Find end of block comment
                    let mut j = i + 2;
                    let mut found_end = false;
                    while j + 1 < len {
                        if bytes[j] == b'*' && bytes[j + 1] == b'/' {
                            found_end = true;
                            break;
                        }
                        j += 1;
                    }
                    let comment_end = if found_end { j } else { len };
                    let comment_slice = &s[i + 2..comment_end];
                    count += comment_slice
                        .split(|ch: char| !ch.is_alphanumeric())
                        .filter(|t| !t.is_empty())
                        .count();

                    if found_end {
                        i = j + 2;
                        code_start = i;
                        continue;
                    } else {
                        i = len;
                        code_start = i;
                        break;
                    }
                }
            }
            i += 1;
        }

        if code_start < len {
            count += Self::token_count_in_code_part(&s[code_start..len]);
        }

        count
    }

    /// Count tokens in a code segment (no comments), mirroring tokenize_code_part rules.
    fn token_count_in_code_part(line: &str) -> usize {
        let mut count = 0usize;
        let mut id_start: Option<usize> = None;

        for (i, ch) in line.char_indices() {
            if ch.is_ascii_alphanumeric() || ch == '_' {
                if id_start.is_none() {
                    id_start = Some(i);
                }
            } else if ch.is_whitespace() {
                if let Some(start) = id_start.take() {
                    count += Self::split_identifier_count(&line[start..i]);
                }
            } else {
                if let Some(start) = id_start.take() {
                    count += Self::split_identifier_count(&line[start..i]);
                }
                // symbol token
                count += 1;
            }
        }
        if let Some(start) = id_start.take() {
            count += Self::split_identifier_count(&line[start..]);
        }
        count
    }

    /// Count subtokens for an identifier (snake_case, camelCase, PascalCase, digits, acronyms)
    fn split_identifier_count(ident: &str) -> usize {
        let mut total = 0usize;
        for chunk in ident.split('_') {
            if chunk.is_empty() {
                continue;
            }
            let chars: Vec<char> = chunk.chars().collect();
            if chars.is_empty() {
                continue;
            }
            let mut part_len = 0usize;
            for i in 0..chars.len() {
                if i > 0 {
                    let prev = chars[i - 1];
                    let next = chars.get(i + 1).copied();
                    let ch = chars[i];
                    let lower_to_upper = prev.is_lowercase() && ch.is_uppercase();
                    let upper_seq_then_lower = prev.is_uppercase()
                        && ch.is_uppercase()
                        && next.map_or_else(|| false, |n| n.is_lowercase());
                    // Do not split at letter<->digit boundaries; keep tokens like "v2" intact.
                    if (lower_to_upper || upper_seq_then_lower) && part_len > 0 {
                        total += 1;
                        part_len = 0;
                    }
                }
                part_len += 1;
            }
            if part_len > 0 {
                total += 1;
            }
        }
        total
    }

    fn tokenize_code_part(line: &str, out: &mut Vec<String>) {
        let mut cur = String::new();
        let mut cur_is_id = false;

        let push_cur = |out: &mut Vec<String>, cur: &mut String, cur_is_id: &mut bool| {
            if cur.is_empty() {
                return;
            }
            if *cur_is_id {
                for sub in Self::split_identifier(cur) {
                    out.push(sub);
                }
            } else {
                // push symbol as-is (but lowercased)
                out.push(cur.to_lowercase());
            }
            cur.clear();
            *cur_is_id = false;
        };

        for ch in line.chars() {
            if ch.is_ascii_alphanumeric() || ch == '_' {
                if !cur_is_id {
                    push_cur(out, &mut cur, &mut cur_is_id);
                }
                cur.push(ch);
                cur_is_id = true;
            } else if ch.is_whitespace() {
                push_cur(out, &mut cur, &mut cur_is_id);
            } else {
                if cur_is_id {
                    push_cur(out, &mut cur, &mut cur_is_id);
                }
                out.push(ch.to_string());
            }
        }
        push_cur(out, &mut cur, &mut cur_is_id);
    }
}

impl Tokenizer for CodeTokenizer {
    fn tokenize(&self, input_text: &str) -> Vec<String> {
        Self::tokens_from_code(input_text)
    }
}

// ------------------------- Cozo client trait + DocMeta -------------------------

#[derive(Debug, Clone, Copy)]
pub struct DocMeta {
    pub token_length: usize,
    pub tracking_hash: TrackingHash,
    pub namespace: Uuid,
}

#[derive(Debug, Clone)]
pub struct DocData {
    pub id: Uuid,
    pub meta: DocMeta,
    pub snippet: String,
    pub name: String,
}

impl DocData {
    pub fn from_embed_clone(value: (&EmbeddingData, &String)) -> Self {
        let token_length = CodeTokenizer::count_tokens_in_code(value.1);
        let tracking_hash = value.0.node_tracking_hash; // Use node tracking hash from EmbeddingData
        DocData {
            id: value.0.id,
            meta: DocMeta {
                token_length,
                tracking_hash,
                namespace: value.0.namespace,
            },
            snippet: value.1.clone(),
            name: value.0.name.clone(),
        }
    }
}

// ------------------------- BM25 Indexer -------------------------

/// In-memory BM25 indexer that uses bm25::Embedder + Scorer.
///
/// Example:
/// ```
/// use ploke_db::bm25_index::{Bm25Indexer, DocData, DocMeta, CodeTokenizer};
/// use ploke_core::{RetrievalScope, TrackingHash};
/// use uuid::Uuid;
///
/// let mut idx = Bm25Indexer::new(10.0);
/// let id = Uuid::new_v4();
/// let snippet = String::from("fn add_one(x: i32) -> i32 { x + 1 }");
/// let meta = DocMeta {
///     token_length: CodeTokenizer::count_tokens_in_code(&snippet),
///     tracking_hash: TrackingHash(Uuid::new_v5(&Uuid::NAMESPACE_DNS, snippet.as_bytes())),
///     namespace: Uuid::new_v4(),
/// };
/// let name = String::from("add_one");
/// let doc = DocData { id, meta, snippet, name };
/// idx.upsert_batch(std::iter::once(doc));
/// let res = idx.search("add_one", 5, RetrievalScope::LoadedWorkspace);
/// assert!(!res.is_empty());
/// ```
pub struct Bm25Indexer {
    embedder: bm25::Embedder<u32, CodeTokenizer>,
    scorer: Scorer<Uuid, u32>,
    staged_meta: HashMap<Uuid, DocMeta>,
    docs: HashSet<Uuid>,
    version: &'static str,
}

impl Bm25Indexer {
    /// Create a new indexer. `avgdl` should be an estimate or a fitted value for your corpus.
    pub fn new(avgdl: f32) -> Self {
        let embedder = EmbedderBuilder::<u32, CodeTokenizer>::with_avgdl(avgdl).build();
        let scorer = Scorer::<Uuid, u32>::new();
        Self {
            embedder,
            scorer,
            staged_meta: HashMap::new(),
            docs: HashSet::new(),
            version: TOKENIZER_VERSION,
        }
    }

    pub fn stage_doc_meta(&mut self, id: Uuid, meta: DocMeta) {
        self.staged_meta.insert(id, meta);
    }

    pub fn extend_staged(&mut self, docs: impl IntoIterator<Item = (Uuid, DocMeta)>) {
        self.staged_meta.extend(docs);
    }

    /// Construct a new Bm25Indexer from a corpus Vec<(Uuid, String)>.
    /// This computes average document length (avgdl) from the corpus tokens, builds an
    /// embedder with that avgdl, and indexes all documents. The corpus is consumed.
    pub fn new_from_corpus(corpus: Vec<(Uuid, String)>) -> Self {
        // compute token lengths for each doc first
        let mut total_tokens: usize = 0;
        let mut doc_token_counts: Vec<(Uuid, usize, String)> = Vec::with_capacity(corpus.len());
        for (id, snippet) in corpus.into_iter() {
            let len = CodeTokenizer::count_tokens_in_code(&snippet);
            total_tokens += len;
            // store snippet string temporarily so we can re-embed after building embedder
            doc_token_counts.push((id, len, snippet));
        }
        let n = doc_token_counts.len();
        let avgdl = if n > 0 {
            (total_tokens as f32) / (n as f32)
        } else {
            0.0
        };

        let embedder = EmbedderBuilder::<u32, CodeTokenizer>::with_avgdl(avgdl).build();
        let mut scorer = Scorer::<Uuid, u32>::new();
        let mut docs_set = HashSet::new();

        // now embed and upsert
        for (id, _len, snippet) in doc_token_counts.into_iter() {
            let embedding = embedder.embed(&snippet);
            scorer.upsert(&id, embedding);
            docs_set.insert(id);
        }

        Self {
            embedder,
            scorer,
            staged_meta: HashMap::new(),
            docs: docs_set,
            version: TOKENIZER_VERSION,
        }
    }

    /// Rebuild the in-memory BM25 index from the Cozo database.
    ///
    /// This scans all primary node relations for (id, name, tracking_hash), computes a corpus
    /// average document length using the code-aware tokenizer, builds a new embedder with the
    /// fitted avgdl, and indexes each document using a light-weight representation of the snippet
    /// (the identifier name doubled to provide a small boost).
    ///
    /// The rebuild does not depend on preexisting BM25 metadata and will work on any database
    /// containing the primary node relations with `id`, `name` and `tracking_hash` attributes.
    ///
    /// Returns a fresh Bm25Indexer with the rebuilt state.
    ///
    /// Example (no_run):
    /// ```
    /// # use std::sync::Arc;
    /// # use ploke_core::RetrievalScope;
    /// # use ploke_db::{Database, create_index_primary};
    /// # use ploke_db::bm25_index::Bm25Indexer;
    /// # fn example(db: Arc<Database>) -> Result<(), ploke_db::DbError> {
    /// let idx = Bm25Indexer::rebuild_from_db(db.as_ref())?;
    /// // Searching for an identifier name present in the database should return results:
    /// let _ = idx.search("main", 5, RetrievalScope::LoadedWorkspace);
    /// # Ok(())
    /// # }
    /// ```
    pub fn rebuild_from_db(db: &Database) -> Result<Self, DbError> {
        let items = collect_rebuild_sources(db)?;
        let n = items.len();

        // Compute total token count and prepare compact (id, meta, combined) triples
        let (sum, metas): (usize, Vec<(Uuid, DocMeta, String)>) = items
            .into_iter()
            .map(|(id, name, th, namespace)| {
                let token_len = CodeTokenizer::count_tokens_in_code(&name);
                let meta = DocMeta {
                    token_length: token_len,
                    tracking_hash: th,
                    namespace,
                };
                // Combined text: boost the identifier by doubling it
                let combined = format!("{0} {0}", name);
                (id, meta, combined)
            })
            .fold(
                (0usize, Vec::new()),
                |(acc_sum, mut acc_vec), (id, meta, combined)| {
                    let new_sum = acc_sum + meta.token_length;
                    acc_vec.push((id, meta, combined));
                    (new_sum, acc_vec)
                },
            );

        let avgdl = if n == 0 {
            0.0
        } else {
            (sum as f32) / (n as f32)
        };
        let embedder = EmbedderBuilder::<u32, CodeTokenizer>::with_avgdl(avgdl).build();
        let mut scorer = Scorer::<Uuid, u32>::new();
        let mut staged_meta = HashMap::with_capacity(n);

        for (id, meta, combined) in metas.into_iter() {
            let emb = embedder.embed(&combined);
            scorer.upsert(&id, emb);
            staged_meta.insert(id, meta);
        }

        let docs = staged_meta.keys().cloned().collect();
        Ok(Self {
            embedder,
            scorer,
            staged_meta,
            docs,
            version: TOKENIZER_VERSION,
        })
    }

    /// Index a batch of (uuid, snippet, name) items.
    /// Returns the number of items indexed.
    pub fn index_batch(&mut self, batch: Vec<DocData>) -> usize {
        // TODO: Analyze the performance impact of this additional allocation.
        // - test with and without the `combined = format!(...);`
        // - test accuracy with and without boost
        let inserted = batch.len();
        for DocData {
            id,
            meta,
            snippet,
            name,
        } in batch
        {
            // Boost the identifier by repeating it once before the snippet.
            // The tokenizer will split the identifier into subtokens.
            let combined = format!("{} {} {}", name, name, snippet);
            let embedding = self.embedder.embed(&combined);
            self.scorer.upsert(&id, embedding);
            self.docs.insert(id);
            // Stage per-doc metadata for atomic Finalize
            let tracking_hash = meta.tracking_hash;
            let token_len = meta.token_length;
            self.staged_meta.insert(
                id,
                DocMeta {
                    token_length: token_len,
                    tracking_hash,
                    namespace: meta.namespace,
                },
            );
        }
        inserted
    }

    /// Index a batch of (uuid, snippet, name) items.
    /// Returns the number of items indexed.
    pub fn upsert_batch(&mut self, batch: impl IntoIterator<Item = DocData>) -> usize {
        let mut inserted = 0;
        for DocData {
            id,
            meta,
            snippet,
            name,
        } in batch
        {
            let combined = format!("{} {} {}", name, name, snippet);
            let embedding = self.embedder.embed(&combined);
            self.scorer.upsert(&id, embedding);
            self.docs.insert(id);
            // Stage per-doc metadata for atomic Finalize and avgdl computation
            self.staged_meta.insert(id, meta);
            inserted += 1;
        }
        inserted
    }

    /// Index a batch of (uuid, snippet) pairs.
    /// Returns the number of items indexed.
    pub fn upsert_batch_with_cozo(
        &mut self,
        cozo: &Database,
        batch: impl IntoIterator<Item = DocData>,
    ) -> Result<usize, DbError> {
        let mut inserted = 0;
        let new_iter = batch.into_iter().map(|d| {
            let DocData {
                id,
                meta,
                snippet,
                name,
            } = d;
            let combined = format!("{} {} {}", name, name, snippet);
            let embedding = self.embedder.embed(&combined);
            self.scorer.upsert(&id, embedding);
            // Stage per-doc metadata (keeps parity with index_batch and supports avgdl/finalize)
            self.staged_meta.insert(id, meta);
            self.docs.insert(id);
            inserted += 1;
            (id, meta)
        });
        cozo.upsert_bm25_doc_meta_batch(new_iter)?;
        Ok(inserted)
    }

    /// Remove a document by id (used when file changes and nodes are pruned)
    pub fn remove(&mut self, id: &Uuid) {
        self.scorer.remove(id);
        self.docs.remove(id);
        self.staged_meta.remove(id);
    }

    /// Search with a query string, returning top-k results as ScoredDocument<Uuid>
    pub fn search(
        &self,
        query: &str,
        top_k: usize,
        scope: RetrievalScope,
    ) -> Vec<bm25::ScoredDocument<Uuid>> {
        let qemb = self.embedder.embed(query);
        tracing::debug!("qemb: {qemb:?}");
        let mut matches = self.scorer.matches(&qemb);
        tracing::trace!("matches: {matches:?}");
        if let Some(namespace) = scope.namespace_filter() {
            matches.retain(|doc| {
                self.staged_meta
                    .get(&doc.id)
                    .is_some_and(|meta| meta.namespace == namespace)
            });
        }
        if matches.len() > top_k {
            matches.truncate(top_k);
        }
        matches
    }

    /// Compute average document length (avgdl) from staged metadata.
    /// Returns 0.0 if no documents are staged.
    pub fn compute_avgdl_from_staged(&self) -> f32 {
        let n = self.staged_meta.len();
        if n == 0 {
            return 0.0;
        }
        let total: usize = self.staged_meta.values().map(|m| m.token_length).sum();
        (total as f32) / (n as f32)
    }

    /// Drain staged metadata for persistence during Finalize.
    pub fn drain_staged_meta(&mut self) -> Vec<(Uuid, DocMeta)> {
        self.staged_meta.drain().collect()
    }

    /// Number of documents currently known to the in-memory scorer.
    pub fn doc_count(&self) -> usize {
        self.docs.len()
    }

    /// True if there are no documents in the in-memory scorer.
    pub fn is_empty(&self) -> bool {
        self.docs.is_empty()
    }
}

/// Collect rebuild items for all primary node relations from the database.
///
/// This function is used by rebuild to stream a lightweight corpus without loading entire snippets.
/// It filters out rows where `name` or `tracking_hash` are missing.
///
/// Example (no_run):
/// ```no_run,ignore
/// # use std::sync::Arc;
/// # use ploke_db::bm25_index::collect_rebuild_sources;
/// # use ploke_db::Database;
/// # fn example(db: Arc<Database>) -> Result<(), ploke_db::DbError> {
/// let triples = collect_rebuild_sources(db.as_ref())?;
/// assert!(triples.len() >= 0);
/// # Ok(())
/// # }
/// ```
pub(crate) fn collect_rebuild_sources(
    db: &Database,
) -> Result<Vec<(Uuid, String, TrackingHash, Uuid)>, DbError> {
    use crate::multi_embedding::db_ext::{ANCESTOR_RULES_NOW, METHOD_NODE_ANCESTOR_RULE};

    let mut clauses = Vec::new();
    for node in NodeType::primary_and_assoc_nodes().iter() {
        let rel = node.relation_str();
        clauses.push(format!(
            r#"?[id, name, tracking_hash, namespace] :=
    *{rel}{{ id, name, tracking_hash @ 'NOW' }},
    ancestor[id, mod_id],
    is_root_module[mod_id],
    *file_mod{{ owner_id: mod_id, namespace @ 'NOW' }}"#,
            rel = rel
        ));
    }

    let script = format!(
        r#"
{ANCESTOR_RULES_NOW}
{METHOD_NODE_ANCESTOR_RULE}

is_root_module[id] := *module{{id @ 'NOW'}}, *file_mod{{owner_id: id @ 'NOW'}}

{clauses}
"#,
        clauses = clauses.join("\n\n")
    );

    let mut out: Vec<(Uuid, String, TrackingHash, Uuid)> = Vec::new();
    let res = db.raw_query(&script)?;
    for row in res.rows.iter() {
        if row.len() < 4 {
            continue;
        }
        let id = match &row[0] {
            DataValue::Uuid(UuidWrapper(u)) => *u,
            _ => continue,
        };
        let name = match &row[1] {
            DataValue::Str(s) if !s.is_empty() => s.clone(),
            _ => continue,
        };
        let th = match &row[2] {
            DataValue::Uuid(UuidWrapper(u)) => TrackingHash(*u),
            _ => continue,
        };
        let namespace = match &row[3] {
            DataValue::Uuid(UuidWrapper(u)) => *u,
            _ => continue,
        };
        out.push((id, name.to_string(), th, namespace));
    }
    Ok(out)
}

