            let prior_rels_vec = db.prior_rels_for_plain_backup_import()?;
            db.import_from_backup(&target_file, &prior_rels_vec)
                .map_err(DbError::from)
                .map_err(ploke_error::Error::from)?;
            db.ensure_compilation_unit_relations()
                .map_err(ploke_error::Error::from)?;
            create_index_primary(&db)?;
            Ok(Arc::new(db))
        };
    }

    #[test]
    fn tokenizer_splits_identifiers_and_comments() {
        let t = CodeTokenizer;
        let src = r#"// leading comment
fn FooBar_baz(x: i32) -> i32 { /* block comment */ x + 1 }"#;
        let toks = t.tokenize(src);
        // should include comment words and identifier subtokens
        assert!(toks.iter().any(|s| s == "leading"));
        assert!(toks.iter().any(|s| s == "comment"));
        assert!(toks.iter().any(|s| s == "foo"));
        assert!(toks.iter().any(|s| s == "bar"));
        assert!(toks.iter().any(|s| s == "baz"));
    }

    #[test]
    fn indexer_indexes_and_searches_basic() {
        let id_a = Uuid::new_v4();
        let id_b = Uuid::new_v4();
        let a = String::from("fn add_one(x: i32) -> i32 { x + 1 }");
        let b = String::from(
            "/// does something
fn compute_answer() -> i32 { 42 }",
        );

        // Use corpus constructor to fit avgdl and index both docs
        let idx = Bm25Indexer::new_from_corpus(vec![(id_a, a.clone()), (id_b, b.clone())]);

        // query for 'compute' should return id_b first
        let results = idx.search("compute", 10, RetrievalScope::LoadedWorkspace);
        assert!(!results.is_empty());
        assert_eq!(results[0].id, id_b);

        // query for 'add_one' (identifier) should return id_a first
        let results2 = idx.search("add_one", 10, RetrievalScope::LoadedWorkspace);
        assert!(!results2.is_empty());
        assert_eq!(results2[0].id, id_a);
    }

    #[test]
    fn scorer_scores_higher_for_matching_document() {
        let mut idx = Bm25Indexer::new(10.0);
        let id_a = Uuid::new_v4();
        let id_b = Uuid::new_v4();
        let a = String::from("fn alpha() { println!(\"hello\"); }");
        let b = String::from("fn beta() { println!(\"compute\"); }");

        // Index both docs into the scorer
        let docs = vec![
            DocData {
                id: id_a,
                meta: DocMeta {
                    token_length: CodeTokenizer::count_tokens_in_code(&a),
                    tracking_hash: TrackingHash(Uuid::new_v5(&Uuid::NAMESPACE_DNS, a.as_bytes())),
                    namespace: Uuid::new_v4(),
                },
                snippet: a.clone(),
                name: String::from("alpha"),
            },
            DocData {
                id: id_b,
                meta: DocMeta {
                    token_length: CodeTokenizer::count_tokens_in_code(&b),
                    tracking_hash: TrackingHash(Uuid::new_v5(&Uuid::NAMESPACE_DNS, b.as_bytes())),
                    namespace: Uuid::new_v4(),
                },
                snippet: b.clone(),
                name: String::from("beta"),
            },
        ];
        idx.index_batch(docs);

        let qemb = idx.embedder.embed("compute");
        let score_a = idx.scorer.score(&id_a, &qemb).unwrap_or(0.0);
        let score_b = idx.scorer.score(&id_b, &qemb).unwrap_or(0.0);
        assert!(
            score_b > score_a,
            "expected matching doc to score higher ({} > {})",
            score_b,
            score_a
        );
    }

    #[test]
    fn index_batch_with_cozo_writes_doc_meta() {
        let mut idx = Bm25Indexer::new(10.0);
        let db = TEST_DB_NODES.as_ref().expect("test db init").clone();
        let id = Uuid::new_v4();
        let snippet = String::from(
            "/// docs
fn hello() { println!(\"hi\"); }",
        );
        let meta = DocMeta {
            token_length: CodeTokenizer::count_tokens_in_code(&snippet),
            tracking_hash: TrackingHash(Uuid::new_v5(&Uuid::NAMESPACE_DNS, snippet.as_bytes())),
            namespace: Uuid::new_v4(),
        };
        let docs = vec![DocData {
            id,
            meta,
            snippet: snippet.clone(),
            name: String::from("hello"),
        }];
        let inserted = idx
            .upsert_batch_with_cozo(db.as_ref(), docs)
            .expect("upsert to cozo");
        assert_eq!(inserted, 1);

        // Ensure the in-memory staged metadata captured what we sent
        let staged = idx.staged_meta.get(&id).expect("staged meta missing");
        assert_eq!(staged.token_length, meta.token_length);
        assert_eq!(staged.tracking_hash, meta.tracking_hash);
    }

    #[test]
    fn new_from_corpus_consumes_vec_and_indexes() {
        let id1 = Uuid::new_v4();
        let id2 = Uuid::new_v4();
        let corpus: Vec<(Uuid, String)> = vec![
            (id1, String::from("fn a() {}")),
            (id2, String::from("fn b() {}")),
        ];
        // new_from_corpus takes ownership
        let idx = Bm25Indexer::new_from_corpus(corpus);
        // ensure docs are indexed by searching
        let res = idx.search("a", 10, RetrievalScope::LoadedWorkspace);
        assert!(!res.is_empty());
    }

    #[test]
    fn token_count_matches_tokenize_len_on_simple_input() {
        let t = CodeTokenizer;
        let s = "/// docs\nfn parseJSON_v2(x: i32) { x += 10; }";
        let toks = t.tokenize(s);
        let count = CodeTokenizer::count_tokens_in_code(s);
        assert_eq!(
            toks.len(),
            count,
            "tokenize() and count_tokens_in_code() should agree"
        );
    }

    #[test]
    fn compute_avgdl_from_staged_meta() {
        let mut idx = Bm25Indexer::new(10.0);
        let s1 = "fn first_token() { let x = 1; }";
        let s2 = "fn second_token_longer_name() { let y = 2; }";
        let id1 = Uuid::new_v4();
        let id2 = Uuid::new_v4();
        let m1 = DocMeta {
            token_length: CodeTokenizer::count_tokens_in_code(s1),
            tracking_hash: TrackingHash(Uuid::new_v5(&Uuid::NAMESPACE_DNS, s1.as_bytes())),
            namespace: Uuid::new_v4(),
        };
        let m2 = DocMeta {
            token_length: CodeTokenizer::count_tokens_in_code(s2),
            tracking_hash: TrackingHash(Uuid::new_v5(&Uuid::NAMESPACE_DNS, s2.as_bytes())),
            namespace: Uuid::new_v4(),
        };
        let docs = vec![
            DocData {
                id: id1,
                meta: m1,
                snippet: s1.to_string(),
                name: String::from("first_token"),
            },
            DocData {
                id: id2,
                meta: m2,
                snippet: s2.to_string(),
                name: String::from("second_token_longer_name"),
            },
        ];
        idx.index_batch(docs);
        let expected = (m1.token_length as f32 + m2.token_length as f32) / 2.0;
        let got = idx.compute_avgdl_from_staged();
        assert!(
            (got - expected).abs() < f32::EPSILON,
            "avgdl mismatch: got {got}, expected {expected}"
        );
    }

    #[test]
    fn bm25_specific_crate_scope_filters_before_top_k_truncation() {
        let mut idx = Bm25Indexer::new(10.0);
        let namespace_a = Uuid::new_v4();
        let namespace_b = Uuid::new_v4();

        let in_scope_snippet = "fn alpha_target() { alpha_target(); }".to_string();
        let out_of_scope_snippet =
            "fn alpha_target_bonus() { alpha_target alpha_target alpha_target; }".to_string();

        idx.index_batch(vec![
            DocData {
                id: Uuid::new_v4(),
                meta: DocMeta {
                    token_length: CodeTokenizer::count_tokens_in_code(&in_scope_snippet),
                    tracking_hash: TrackingHash(Uuid::new_v5(
                        &Uuid::NAMESPACE_DNS,
                        in_scope_snippet.as_bytes(),
                    )),
                    namespace: namespace_a,
                },
                snippet: in_scope_snippet,
                name: "alpha_target".to_string(),
            },
            DocData {
                id: Uuid::new_v4(),
                meta: DocMeta {
                    token_length: CodeTokenizer::count_tokens_in_code(&out_of_scope_snippet),
                    tracking_hash: TrackingHash(Uuid::new_v5(
                        &Uuid::NAMESPACE_DNS,
                        out_of_scope_snippet.as_bytes(),
                    )),
                    namespace: namespace_b,
                },
                snippet: out_of_scope_snippet,
                name: "alpha_target_bonus".to_string(),
            },
        ]);

        let unscoped = idx.search("alpha target bonus", 1, RetrievalScope::LoadedWorkspace);
        assert_eq!(
            unscoped.len(),
            1,
            "unscoped top_k=1 should truncate to one hit"
        );
        let unscoped_namespace = idx
            .staged_meta
            .get(&unscoped[0].id)
            .map(|meta| meta.namespace)
            .expect("unscoped hit should have staged metadata");
        assert_eq!(
            unscoped_namespace, namespace_b,
            "unscoped top_k=1 should prefer the stronger out-of-scope document"
        );

        let scoped = idx.search(
            "alpha target bonus",
            1,
            RetrievalScope::SpecificCrate(CrateId::new(namespace_a)),
        );
        assert_eq!(
            scoped.len(),
            1,
            "scoped top_k=1 should still return one in-scope hit"
        );
        let scoped_namespace = idx
            .staged_meta
            .get(&scoped[0].id)
            .map(|meta| meta.namespace)
            .expect("scoped hit should have staged metadata");
        assert_eq!(
            scoped_namespace, namespace_a,
            "crate scope must be applied before top_k truncation"
        );
    }

    #[tokio::test]
    async fn bm25_service_index_search_finalize_roundtrip() {
        let db = TEST_DB_NODES.as_ref().expect("test db init").clone();
        let tx = bm25_service::start_default(db).expect("start bm25 service");

        // Prepare a document with a unique token to avoid accidental collisions
        let id = Uuid::new_v4();
        let snippet = String::from("fn unique_xylophone_token() { let compute = 1; }");
        let meta = DocMeta {
            token_length: CodeTokenizer::count_tokens_in_code(&snippet),
            tracking_hash: TrackingHash(Uuid::new_v5(&Uuid::NAMESPACE_DNS, snippet.as_bytes())),
            namespace: Uuid::new_v4(),
        };
        let doc = DocData {
            id,
            meta,
            snippet: snippet.clone(),
            name: String::from("unique_xylophone_token"),
        };

        // Index
        tx.send(bm25_service::Bm25Cmd::IndexBatch { docs: vec![doc] })
            .await
            .expect("send index batch");

        // Search
        let (resp_tx, resp_rx) = tokio::sync::oneshot::channel();
        tx.send(bm25_service::Bm25Cmd::Search {
            query: "xylophone".to_string(),
            top_k: 5,
            scope: RetrievalScope::LoadedWorkspace,
            resp: resp_tx,
        })
        .await
        .expect("send search");
        let results = resp_rx.await.expect("await search");
        assert!(!results.is_empty(), "expected non-empty search results");
        assert_eq!(results[0].0, id, "expected the indexed doc to rank first");

        // Finalize
        let (f_tx, f_rx) = tokio::sync::oneshot::channel();
        tx.send(bm25_service::Bm25Cmd::FinalizeSeed { resp: f_tx })
            .await
            .expect("send finalize");
        let ack = f_rx.await.expect("await finalize ack");
        assert!(ack.is_ok(), "finalize ack should be Ok");
    }

    #[test]
    fn rebuild_from_db_builds_index_and_searches_by_name() {
        let db = TEST_DB_NODES.as_ref().expect("test db init").clone();
        let idx = Bm25Indexer::rebuild_from_db(db.as_ref()).expect("rebuild from db");
        let triples = collect_rebuild_sources(db.as_ref()).expect("collect names");
        assert!(
            !triples.is_empty(),
            "expected some primary nodes to rebuild from"
        );
        let query = triples[0].1.clone();
        let results = idx.search(&query, 5, RetrievalScope::LoadedWorkspace);
        assert!(
            !results.is_empty(),
            "expected non-empty results for known identifier"
        );
    }

    #[tokio::test]
    async fn bm25_service_rebuild_command_reindexes_from_db() {
        use std::time::Duration;
        let db = TEST_DB_NODES.as_ref().expect("test db init").clone();
        let tx = bm25_service::start_default(db.clone()).expect("start bm25 service");

        // Trigger rebuild
        tx.send(bm25_service::Bm25Cmd::Rebuild)
            .await
            .expect("send rebuild");

        // Choose a known identifier from the database
        let triples = collect_rebuild_sources(db.as_ref()).expect("collect names");
        assert!(!triples.is_empty(), "expected corpus from DB");
        let query = triples[0].1.clone();

        // Retry a few times to allow the actor to complete the rebuild before searching.
        let mut got: Vec<(Uuid, f32)> = Vec::new();
        for _ in 0..10 {
            let (resp_tx, resp_rx) = tokio::sync::oneshot::channel();
            tx.send(bm25_service::Bm25Cmd::Search {
                query: query.clone(),
                top_k: 5,
                scope: RetrievalScope::LoadedWorkspace,
                resp: resp_tx,
            })
            .await
            .expect("send search");
            let r = resp_rx.await.expect("await search");
            if !r.is_empty() {
                got = r;
                break;
            }
            tokio::time::sleep(Duration::from_millis(25)).await;
        }
        assert!(!got.is_empty(), "expected results after rebuild");
    }

    /// TDD test: Verify that `collect_rebuild_sources` includes Method nodes.
    ///
    /// This test will initially FAIL because `collect_rebuild_sources` only iterates
    /// over `NodeType::primary_nodes()`, which does not include Method.
    ///
    /// **Implementation needed:**
    /// 1. Change `primary_nodes()` to `primary_and_assoc_nodes()` in `collect_rebuild_sources`
    /// 2. Add METHOD_NODE_ANCESTOR_RULE to the CozoScript for Method nodes (Option B)
    #[test]
    fn collect_rebuild_sources_includes_method_nodes() {
        let db = TEST_DB_NODES.as_ref().expect("test db init").clone();
        let triples = collect_rebuild_sources(db.as_ref()).expect("collect names");

        // First, verify we have some triples
        assert!(!triples.is_empty(), "expected some nodes to rebuild from");

        // Get the total count of methods in the database for context
        let method_count_script = r#"?[count(id)] := *method { id, name @ 'NOW' }"#;
        let method_count_result = db
            .raw_query(method_count_script)
            .expect("query method count");
        let total_methods = match &method_count_result.rows[0][0] {
            DataValue::Num(cozo::Num::Int(n)) => *n as usize,
            _ => 0,
        };
        eprintln!("Total methods in database: {}", total_methods);

        // THE FAILING ASSERTION: Method nodes should be included in rebuild sources
        // This will FAIL initially because collect_rebuild_sources doesn't process methods
        let method_triples: Vec<_> = triples
            .iter()
            .filter(|(id, name, _th, _ns)| {
                // Check if this ID exists in the method relation
                let check_script = format!(
                    r#"?[id] := *method {{ id, name @ 'NOW' }}, id == {}"#,
                    cozo_datavalue_uuid(*id)
                );
                db.raw_query(&check_script)
                    .map(|r| !r.rows.is_empty())
                    .unwrap_or(false)
            })
            .collect();

        eprintln!(
            "Method triples found in rebuild sources: {}",
            method_triples.len()
        );

        assert!(
            !method_triples.is_empty(),
            "Expected Method nodes to be included in collect_rebuild_sources, but found none. \
             This indicates that collect_rebuild_sources is not iterating over NodeType::Method. \
             To fix: Change primary_nodes() to primary_and_assoc_nodes() and add METHOD_NODE_ANCESTOR_RULE for Method nodes."
        );

        eprintln!(
            "SUCCESS: collect_rebuild_sources includes {} Method nodes",
            method_triples.len()
        );
    }
}

/// Helper to format a UUID for CozoScript
fn cozo_datavalue_uuid(id: Uuid) -> String {
    format!("to_uuid(\"{}\")", id)
}

